static bool check(char *pattern, char *value, int la, int lb) {
  int n = strlen(value);
  const char *a = NULL, *b = NULL;
  int aLen = -1, bLen = -1, pos = 0;
  for (int i = 0; pattern[i]; i++) {
    if (pattern[i] == 'a') {
      if (pos + la > n) return false;
      if (a == NULL) {
        a = value + pos;
        aLen = la;
      } else if (aLen != la || strncmp(a, value + pos, la) != 0) {
        return false;
      }
      pos += la;
    } else {
      if (pos + lb > n) return false;
      if (b == NULL) {
        b = value + pos;
        bLen = lb;
      } else if (bLen != lb || strncmp(b, value + pos, lb) != 0) {
        return false;
      }
      pos += lb;
    }
  }
  if (pos != n) return false;
  if (a && b && aLen == bLen && strncmp(a, b, aLen) == 0) return false;
  return true;
}

bool patternMatching(char *pattern, char *value) {
  int n = strlen(value), np = strlen(pattern);
  if (np == 0) return n == 0;
  int na = 0, nb = 0;
  for (int i = 0; i < np; i++) {
    if (pattern[i] == 'a') {
      na++;
    } else {
      nb++;
    }
  }
  for (int la = 0; la <= n; la++) {
    if (na * la > n) break;
    int rem = n - na * la;
    if (nb == 0) {
      if (rem == 0 && check(pattern, value, la, 0)) return true;
    } else {
      if (rem % nb != 0) continue;
      int lb = rem / nb;
      if (check(pattern, value, la, lb)) return true;
    }
  }
  return false;
}

class Solution {
  bool check(const string &pattern, const string &value, int la, int lb) {
    int n = value.size();
    int aPos = -1, bPos = -1, aLen = -1, bLen = -1, pos = 0;
    for (char c : pattern) {
      if (c == 'a') {
        if (pos + la > n) return false;
        if (aPos == -1) {
          aPos = pos;
          aLen = la;
        } else if (aLen != la || value.compare(aPos, la, value, pos, la) != 0) {
          return false;
        }
        pos += la;
      } else {
        if (pos + lb > n) return false;
        if (bPos == -1) {
          bPos = pos;
          bLen = lb;
        } else if (bLen != lb || value.compare(bPos, lb, value, pos, lb) != 0) {
          return false;
        }
        pos += lb;
      }
    }
    if (pos != n) return false;
    if (aPos != -1 && bPos != -1 && aLen == bLen && value.compare(aPos, aLen, value, bPos, bLen) == 0) return false;
    return true;
  }

public:
  bool patternMatching(string pattern, string value) {
    int n = value.size();
    if (pattern.empty()) return n == 0;
    int na = 0;
    for (char c : pattern) if (c == 'a') na++;
    int nb = pattern.size() - na;
    for (int la = 0; la <= n; la++) {
      if (na * la > n) break;
      int rem = n - na * la;
      if (nb == 0) {
        if (rem == 0 && check(pattern, value, la, 0)) return true;
      } else {
        if (rem % nb != 0) continue;
        if (check(pattern, value, la, rem / nb)) return true;
      }
    }
    return false;
  }
};

func patternMatching(pattern string, value string) bool {
	n := len(value)
	if len(pattern) == 0 {
		return n == 0
	}
	na := strings.Count(pattern, "a")
	nb := len(pattern) - na
	check := func(la, lb int) bool {
		a, b := "", ""
		hasA, hasB := false, false
		pos := 0
		for i := 0; i < len(pattern); i++ {
			if pattern[i] == 'a' {
				if pos+la > n {
					return false
				}
				sub := value[pos : pos+la]
				if !hasA {
					a, hasA = sub, true
				} else if a != sub {
					return false
				}
				pos += la
			} else {
				if pos+lb > n {
					return false
				}
				sub := value[pos : pos+lb]
				if !hasB {
					b, hasB = sub, true
				} else if b != sub {
					return false
				}
				pos += lb
			}
		}
		if pos != n {
			return false
		}
		if hasA && hasB && a == b {
			return false
		}
		return true
	}
	for la := 0; la <= n; la++ {
		if na*la > n {
			break
		}
		rem := n - na*la
		if nb == 0 {
			if rem == 0 && check(la, 0) {
				return true
			}
		} else {
			if rem%nb != 0 {
				continue
			}
			if check(la, rem/nb) {
				return true
			}
		}
	}
	return false
}

class Solution {
  private boolean check(String pattern, String value, int la, int lb) {
    int n = value.length();
    int aPos = -1, bPos = -1, aLen = -1, bLen = -1, pos = 0;
    for (int i = 0; i < pattern.length(); i++) {
      if (pattern.charAt(i) == 'a') {
        if (pos + la > n) return false;
        if (aPos == -1) {
          aPos = pos;
          aLen = la;
        } else if (aLen != la || !value.regionMatches(aPos, value, pos, la)) {
          return false;
        }
        pos += la;
      } else {
        if (pos + lb > n) return false;
        if (bPos == -1) {
          bPos = pos;
          bLen = lb;
        } else if (bLen != lb || !value.regionMatches(bPos, value, pos, lb)) {
          return false;
        }
        pos += lb;
      }
    }
    if (pos != n) return false;
    if (aPos != -1 && bPos != -1 && aLen == bLen && value.regionMatches(aPos, value, bPos, bLen)) return false;
    return true;
  }

  public boolean patternMatching(String pattern, String value) {
    int n = value.length();
    if (pattern.isEmpty()) return n == 0;
    int na = 0;
    for (int i = 0; i < pattern.length(); i++) if (pattern.charAt(i) == 'a') na++;
    int nb = pattern.length() - na;
    for (int la = 0; la <= n; la++) {
      if (na * la > n) break;
      int rem = n - na * la;
      if (nb == 0) {
        if (rem == 0 && check(pattern, value, la, 0)) return true;
      } else {
        if (rem % nb != 0) continue;
        if (check(pattern, value, la, rem / nb)) return true;
      }
    }
    return false;
  }
}

class Solution:
    def patternMatching(self, pattern: str, value: str) -> bool:
        n = len(value)
        if not pattern:
            return n == 0
        na = pattern.count("a")
        nb = len(pattern) - na

        def check(la: int, lb: int) -> bool:
            a = b = None
            pos = 0
            for c in pattern:
                if c == "a":
                    if pos + la > n:
                        return False
                    sub = value[pos:pos + la]
                    if a is None:
                        a = sub
                    elif a != sub:
                        return False
                    pos += la
                else:
                    if pos + lb > n:
                        return False
                    sub = value[pos:pos + lb]
                    if b is None:
                        b = sub
                    elif b != sub:
                        return False
                    pos += lb
            if pos != n:
                return False
            if a is not None and b is not None and a == b:
                return False
            return True

        for la in range(n + 1):
            if na * la > n:
                break
            rem = n - na * la
            if nb == 0:
                if rem == 0 and check(la, 0):
                    return True
            else:
                if rem % nb != 0:
                    continue
                if check(la, rem // nb):
                    return True
        return False

impl Solution {
  pub fn pattern_matching(pattern: String, value: String) -> bool {
    let n = value.len();
    let p = pattern.as_bytes();
    if p.is_empty() {
      return n == 0;
    }
    let na = p.iter().filter(|&&c| c == b'a').count();
    let nb = p.len() - na;

    let check = |la: usize, lb: usize| -> bool {
      let (mut a, mut b): (Option<&str>, Option<&str>) = (None, None);
      let mut pos = 0usize;
      for &c in p {
        let len = if c == b'a' { la } else { lb };
        if pos + len > n {
          return false;
        }
        let sub = &value[pos..pos + len];
        if c == b'a' {
          match a {
            None => a = Some(sub),
            Some(prev) => {
              if prev != sub {
                return false;
              }
            }
          }
        } else {
          match b {
            None => b = Some(sub),
            Some(prev) => {
              if prev != sub {
                return false;
              }
            }
          }
        }
        pos += len;
      }
      if pos != n {
        return false;
      }
      if let (Some(x), Some(y)) = (a, b) {
        if x == y {
          return false;
        }
      }
      true
    };

    for la in 0..=n {
      if na * la > n {
        break;
      }
      let rem = n - na * la;
      if nb == 0 {
        if rem == 0 && check(la, 0) {
          return true;
        }
      } else {
        if rem % nb != 0 {
          continue;
        }
        if check(la, rem / nb) {
          return true;
        }
      }
    }
    false
  }
}

const patternMatching = (pattern: string, value: string): boolean => {
  const n = value.length;
  if (pattern.length === 0) return n === 0;
  const na = pattern.split('').filter((c) => c === 'a').length;
  const nb = pattern.length - na;

  const check = (la: number, lb: number): boolean => {
    let a: string | null = null;
    let b: string | null = null;
    let pos = 0;
    for (const c of pattern) {
      if (c === 'a') {
        if (pos + la > n) return false;
        const sub = value.slice(pos, pos + la);
        if (a === null) a = sub;
        else if (a !== sub) return false;
        pos += la;
      } else {
        if (pos + lb > n) return false;
        const sub = value.slice(pos, pos + lb);
        if (b === null) b = sub;
        else if (b !== sub) return false;
        pos += lb;
      }
    }
    if (pos !== n) return false;
    if (a !== null && b !== null && a === b) return false;
    return true;
  };

  for (let la = 0; la <= n; la++) {
    if (na * la > n) break;
    const rem = n - na * la;
    if (nb === 0) {
      if (rem === 0 && check(la, 0)) return true;
    } else {
      if (rem % nb !== 0) continue;
      if (check(la, rem / nb)) return true;
    }
  }
  return false;
};
